        raise KleanExportError(
            "K definition requires a file outside the frozen workspace: "
            f"{required}"
        )
    if not resolved.exists():
        if resolved.suffix == ".k":
            raise KleanExportError(
                f"K definition requires a missing workspace .k file: {required}"
            )
        return None

